try{const old=JSON.parse(localStorage.getItem(storageKey));if(old?.version===1){saved={...saved,...old,seen:Array.isArray(old.seen)?old.seen.filter(k=>SCENES[k]):[]};prefs={...prefs,...old.prefs};if(saved.checkpoint&&!restore(saved.checkpoint,prefs.difficulty))saved.checkpoint=null;if(saved.scene&&!SCENES[saved.scene])saved.scene=null;}}catch{storageOK=false;}
