function configure(){music.configure({enabled:!silentSession&&!prefs.muted&&prefs.music>0,volume:prefs.music});dialogue.configure({enabled:!silentSession&&!prefs.muted&&prefs.voice>0,volume:prefs.voice,subtitles:prefs.subtitles||silentSession||prefs.muted});document.body.dataset.muted=String(silentSession||!!prefs.muted);$('speech').muted=silentSession||!!prefs.muted||!prefs.voice;document.body.classList.toggle('large-captions',prefs.large);if(fxGain)fxGain.gain.value=silentSession||prefs.muted?0:prefs.effects*.5;}
function fx(kind,volume=1){if(silentSession||prefs.muted||!prefs.effects||state==='pause')return;try{fxContext??=new(window.AudioContext||window.webkitAudioContext)();if(!fxGain){fxGain=fxContext.createGain();fxGain.connect(fxContext.destination);}fxGain.gain.value=prefs.effects*.5;fxContext.resume();const ctx=fxContext,t=ctx.currentTime;
 if(kind==='bell'){for(const f of [510,1021,1407]){const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.setValueAtTime(.12*volume,t);g.gain.exponentialRampToValueAtTime(.0001,t+2.5);o.connect(g);g.connect(fxGain);o.start();o.stop(t+2.6);}return;}
 const len=kind==='shot'?.6:kind==='hurt'?.3:kind==='foot'?.09:.18,b=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*len),ctx.sampleRate),d=b.getChannelData(0);
 for(let i=0;i<d.length;i++){const p=i/d.length;d[i]=(Math.random()*2-1)*Math.pow(1-p,kind==='shot'?4:2)*volume*(kind==='foot'?.15:1);}
 const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter();src.buffer=b;filter.type='lowpass';filter.frequency.value=kind==='shot'?1800:kind==='foot'?160:600;src.connect(filter);filter.connect(fxGain);src.start();}catch{}}
