function resetInput(){keys={};touchPoint=null;hadPointerLock=false;touchCrouch=false;touchAim=false;pressed={};washStrokes=[];fire=false;aim=false;autoWalk=false;interacting=false;try{if(document.pointerLockElement)document.exitPointerLock();}catch{}}
