function home(){hide();film=null;replay=false;missionReplay=false;replayCheckpoint=null;music.select('home');music.resume();const started=saved.checkpoint||saved.scene;
 ui.innerHTML=`<section class="menu"><header class="topline"><a class="brand" href="./">DC <i>/</i> US HISTORY</a><nav>${btn('Chapters','chapters','quiet')}${btn('Settings','settings','quiet')}</nav></header><div class="hero"><p class="eyebrow">Chapter 06 · America’s War for Independence</p><h1>THE LONG<br><span>ROAD HOME</span></h1><p class="lede">A promise kept. A country breaking.<br>From the first shot to a country divided.</p><div class="row">${btn(started&&!saved.complete?'Continue the campaign →':'Begin the campaign →','start')}${btn('Mission select','missions','secondary')}</div><div class="edition"><span>NOW PLAYING · COUNTRY AGAINST ITSELF</span><span>1775–1780</span><span>HEADPHONES RECOMMENDED</span></div>${!storageOK?'<p class="save-warning">Browser saving is unavailable. Keep this tab open to retain your session.</p>':''}</div><div class="chapter-number">06</div><footer class="menu-foot"><span>AN ORIGINAL STORY THROUGH REAL HISTORY</span><div class="row">${btn('Story scenes','scenes','quiet')}${btn('Controls','controls','quiet')}${btn('History & credits','archive','quiet')}</div></footer></section>`;
}
function chapters(){hide();setState('chapters');panel(`<p class="eyebrow">DC / US History</p><h1>Three roads through history.</h1><div class="chapters"><a class="chapter-card" href="chapter4.html"><span>CHAPTER 04</span><strong>Crown & Current</strong><p>1676–1763 · Building an empire.</p><span>Play →</span></a><a class="chapter-card" href="chapter5.html"><span>CHAPTER 05</span><strong>The Last Dispatch</strong><p>1763–1774 · A city on the edge.</p><span>Play →</span></a><button class="chapter-card" data-action="home"><span>CHAPTER 06 · CAMPAIGN</span><strong>The Long Road Home</strong><p>1775–1776 · Powder Road to the New York campaign of 1776.</p><span>Play →</span></button></div><div class="row">${btn('Back','home','quiet')}</div>`);}
function scenes(){hide();setState('scenes');panel(`<p class="eyebrow">The Long Road Home · screening room</p><h1>The people you carry.</h1><p>Includes spoilers through Country Against Itself. Replays leave your campaign checkpoint intact.</p><div class="scene-list">${Object.entries(SCENES).map(([id,s],i)=>btn(`<span>${String(i+1).padStart(2,'0')} · ${esc(s.place)}</span><strong>${esc(s.title)}</strong>`,'scene','scene-card',`data-scene="${id}"`)).join('')}</div>${btn('Back','home','quiet')}`);}
function missions(){hide();missionReplay=false;setState('missions');panel(`<p class="eyebrow">Chapter 6 · Campaign missions</p><h1>Choose your road.</h1><p>Replay any mission. Your story checkpoint stays where you left it.</p><div class="mission-list">${Object.entries(LEVELS).map(([id,l],i)=>btn(`<span>${String(i+1).padStart(2,'0')} / ${l.mode||['REUNION','STEALTH','RESCUE','DEFENSE'][i]}</span><strong>${esc(l.title)}</strong><p>${l.description||['Bring Ward out of the prison courtyard.','Warn the countryside. Stay out of the lantern light.','Cross the green between volleys. Bring them home.','Fire. Reload in cover. Keep the wagon moving.'][i]}</p><i>Deploy →</i>`,'mission','mission-card',`data-mission="${id}"`)).join('')}</div><div class="row">${btn('Back','home','quiet')}${btn('Restart the story','new-story','quiet')}</div>`);}
function newStory(){setState('new-story');panel(`<p class="eyebrow">A new beginning</p><h1>Back to the prison gates?</h1><p>This replaces your current Chapter 6 checkpoint. Your settings and the other chapters stay saved.</p><div class="row">${btn('Begin again','confirm-new')}${btn('Keep my progress','missions','secondary')}</div>`,true);}
function missionComplete(){resetInput();dialogue.stop();setState('mission-complete');music.select('home');const shots=model.shotsFired||0;panel(`<p class="eyebrow">Mission complete · ${esc(LEVELS[model.level].title)}</p><h1>${model.inland?'The people reached the road.':model.south?'The names came through.':model.wider?'Both boats. Every name.':model.winter?'The next job, together.':model.albany?'The roads brought us here.':model.philadelphia?'The people and papers came through.':model.crossing?'The section came through.':model.retreat?'The crew came through.':model.paper?'The words got through.':model.lift?'The horizon lifted.':model.promise?'A passage kept.':model.level==='breeds'?'The people we carry.':model.level==='ticonderoga'?'The guns are ours.':model.level==='concord'?'The wagon made it.':model.level==='lexington'?'No one left behind.':model.level==='night'?'The warning got through.':'A promise kept.'}</h1><p>${Math.floor(model.time/60)}:${String(Math.floor(model.time%60)).padStart(2,'0')} on the road${model.level==='breeds'?' · Two wounded brought out · Crew together':model.level==='ticonderoga'?(model.fort.alarm?' · Nathan brought back safely':' · Undetected approach'):model.winter&&model.level==='drill'?' · Detachment trained':shots?' · '+Math.round(model.kills/shots*100)+'% accuracy':''}</p><div class="row">${btn('Choose a mission','missions')}${btn('Return to story','campaign','secondary')}</div>`,true);}
function controls(back='home'){setState('controls');panel(`<p class="eyebrow">Controls</p><h1>Stay close. Keep moving.</h1><div class="controls"><div><kbd>W A S D</kbd> Move</div><div>Mouse / <kbd>← ↑ ↓ →</kbd> Look</div><div><kbd>E</kbd> Interact near a person or object</div><div><kbd>C</kbd> Hold to crouch</div><div><kbd>Shift</kbd> Sprint</div><div><kbd>Space</kbd> Jump / brake / timed axe or press stroke / advance scene</div><div>Click / <kbd>F</kbd> Fire when armed</div><div>Right mouse / <kbd>Q</kbd> Aim</div><div><kbd>R</kbd> Reload</div><div><kbd>V</kbd> Toggle auto-walk; WASD cancels</div><div><kbd>P / Esc</kbd> Pause</div><div><kbd>M</kbd> Mute all sound</div><div>Touch: swipe to look; LOW and AIM toggle</div></div><p>Tap E to begin an interaction; moving away cancels it. Watch the warning before a Lexington volley. In Concord, E at the supply crate restores health and cartridges once. At Breed’s Hill, E at the line directs a volley; E at your reserve resupplies once. Keep low while the militia reload. Reload behind cover to recover. On the water, WASD rows relative to your view, Shift rows hard, and C toggles quiet strokes. Release movement to brake. Reeds hide a slow boat; change direction when a shot is marked on the water. On the gun road, WASD pulls once hitched, Space brakes the load, and the hauling camera keeps the rope and gun in view. Move the ballast across the sledge when Mara calls for it. On the Delaware, W drives the ferry, A and D turn the tiller, and S or Space steadies it. Recover equipment and take the landing rope only at a slow speed. On the East River, A and D work the left and right oars. W alternates them. S or Space brakes. The oars turn the boat; mouse and arrows look independently. At the hand press, E feeds or takes a sheet, D slides in, Space presses inside the pale band, and A slides out. W or S steps away; E at the handles resumes. At Charleston, Space strikes only inside the pale axe band. Walk beside the loaded patient cart; Space holds its brake. Isaiah’s harbor boat uses W to row, A / D to steer and S / Space to steady. The patrol lantern can see a nearby boat; slow in the western shelter before leaving. Story difficulty gives more protection and aiming assistance.</p><div class="row">${btn('Back',back)}</div>`,true);}
function archive(){hide();setState('archive');panel(`<p class="eyebrow">Chapter 6 · Part I</p><h1>The history behind the road.</h1><p>Playable now: Ward’s release, the Powder Road, Lexington, the retreat from Concord, The Guns North at Ticonderoga, Hold Until Empty at Breed’s Hill, A King’s Promise in Virginia and North Carolina, and Lift the Horizon through the winter gun road, Dorchester Heights, and Boston’s evacuation, followed by A Country on Paper’s Philadelphia press and diplomatic dispatch. No Ground Left follows the New York defeats and local rescues. Across the Black Water continues through the Delaware, Trenton and Princeton. A City Is Not an Army follows Brandywine and the Congress evacuation. Three Roads to Albany continues through route denial, a protected parley, Bemis Heights, the Hudson river watch and Saratoga. The Winter Line continues through a thawing supply road, divided camp work and von Steuben’s drill, ending with the dated French-alliance celebration. The Wider War follows the Monmouth section, a coastal supply passage, global-war reports and the Connecticut fire rescue. The South Breaks follows three dated siege phases, patient-cart relief, a timber rescue, the historical surrender and Isaiah’s guarded harbor passage. Country Against Itself adds Camden’s losing squad retreat, an oath checkpoint, two physical house exits and dated December supply work. Later Chapter 6 missions remain in development.</p>${FACTS.map(([title,text,source])=>`<article class="fact"><h2>${esc(title)}</h2><p>${esc(text)}</p><small>${esc(source)}</small></article>`).join('')}<article class="fact"><h2>Production</h2><p>${C6_VOICES.length} prerecorded synthetic performances using stock Kokoro voices; ${Object.keys(C6_SCORE).length} original instrumental arrangements. Real-time scenes, original procedural environments, and the established crew rigs. No account, microphone, or AI service is needed to play.</p><p><a href="C6-SOURCES.md" target="_blank">Sources and historical scope</a> · <a href="C6-CREDITS.md" target="_blank">Voice, music, and art credits</a></p></article>${btn('Back','home','quiet')}`);}
function settings(back=state==='pause'?'pause':'home'){settingsBack=back;setState('settings');const slider=(id,label,help)=>`<label class="setting"><span>${label}<small>${help}</small></span><input aria-label="${label}" type="range" data-setting="${id}" min="0" max="1" step=".05" value="${prefs[id]}"></label>`;
 panel(`<p class="eyebrow">Settings</p><h1>Make room for the story.</h1><label class="setting"><span>Mute all sound<small>${silentSession?'This preview session is locked to silent.':'Also available with the M key.'}</small></span><input aria-label="Mute all sound" type="checkbox" data-setting="muted" ${prefs.muted||silentSession?'checked':''} ${silentSession?'disabled':''}></label>${slider('voice','Voice volume','Dialogue remains captioned if a recording fails.')}${slider('music','Music volume','The score lowers during speech.')}${slider('effects','Effects volume','Gunfire, footsteps, and interactions.')}<label class="setting"><span>Difficulty<small>Story reduces damage and adds aiming assistance.</small></span><select aria-label="Difficulty" data-setting="difficulty"><option value="normal" ${prefs.difficulty==='normal'?'selected':''}>Normal</option><option value="story" ${prefs.difficulty==='story'?'selected':''}>Story</option></select></label><label class="setting"><span>Look sensitivity</span><input aria-label="Look sensitivity" type="range" data-setting="sensitivity" min=".3" max="2" step=".1" value="${prefs.sensitivity}"></label><label class="setting"><span>Graphics<small>Performance reduces shadows and resolution.</small></span><select aria-label="Graphics" data-setting="quality"><option value="high" ${prefs.quality==='high'?'selected':''}>Detailed</option><option value="low" ${prefs.quality==='low'?'selected':''}>Performance</option></select></label>${[['subtitles','Subtitles'],['large','Larger captions'],['reduced','Reduced camera motion']].map(([k,v])=>`<label class="setting"><span>${v}</span><input type="checkbox" data-setting="${k}" ${prefs[k]?'checked':''}></label>`).join('')}<div class="row">${btn('Done','settings-done')}</div>`,true);}
function errorScreen(){setState('error');panel(`<p class="eyebrow">Graphics unavailable</p><h1>The road couldn’t open.</h1><p>This browser could not initialize WebGL. Try a browser with hardware acceleration enabled, or return to another chapter.</p><div class="row">${btn('Try again','retry-render')}${btn('Chapters','chapters','secondary')}</div>`,true);}
function start(){replay=false;missionReplay=false;if(fixture&&LEVELS[fixture]){const phase=sessionParams.get('phase');begin(fixtureState(fixture,phase,prefs.difficulty));if(phase==='break'&&fixture==='breeds')playScene('hillBreak');return;}if(saved.complete){saved.complete=false;saved.checkpoint=null;saved.scene='release';}if(saved.scene)return playScene(saved.scene);if(saved.checkpoint){model=restore(saved.checkpoint,prefs.difficulty);if(model)return begin(model);}playScene('release');}
function checkpoint(){if(missionReplay){replayCheckpoint=snapshot(model);saveUntil=time+2.8;return;}saved.checkpoint=snapshot(model);saved.scene=null;persist();saveUntil=time+2.8;}
function begin(s){if(!ensureWorld())return errorScreen();model=missionReplay?s:carryOutcome(s,saved);world.load(s.level);film=null;resetInput();dialogue.reset();setState('play');ui.innerHTML='';music.select(s.level==='tidewater'?(s.stage>=4?'battle':s.stage>=3?'tension':'tide'):s.level==='breeds'?(s.stage>=7?'tension':hillDefending(s)?'ridge':'tension'):LEVELS[s.level].music);music.resume();checkpoint();canvas.focus();last=performance.now();updateHUD();if(s.level==='release'&&s.stage===1)say('releasewalk');}
function playScene(key,preview=false){if(!ensureWorld())return errorScreen();resetInput();dialogue.stop();replay=preview;film={key,beat:0,time:0,elapsed:0,spoken:false,shot:false};world.load(SCENES[key].level);setState('film');ui.innerHTML='';if(!preview&&!missionReplay){saved.scene=key;persist();}if(SCENES[key].music){music.select(SCENES[key].music);music.resume();}else music.pause();$('scene-title').textContent=SCENES[key].title;$('scene-place').textContent=SCENES[key].place;last=performance.now();}
function advance(){if(!film)return;dialogue.stop();film.beat++;film.time=0;film.spoken=false;if(film.beat>=SCENES[film.key].lines.length)finishScene();}
function finishScene(skipped=false){if(!film)return;const key=film.key;dialogue.stop();film=null;if(replay){replay=false;scenes();return;}if(!missionReplay)rememberScene(saved,key,skipped);const target=SCENES[key].after;document.body.dataset.nextScene=target;if(!missionReplay){saved.scene=null;persist();}if(missionReplay&&['northEnding','hillLegacy','promiseCoda','liftHome','paperCoda','retreatEnding','crossingEnding','philadelphiaEnding','albanySurrender','winterAlliance','widerEnding','southEnding','inlandEnding'].includes(key))return missionComplete();if(target==='checkpoint'){const point=missionReplay?replayCheckpoint:saved.checkpoint;const resumed=restore(point,prefs.difficulty);if(resumed){if(resumed.fort)resumed.fort.crew=1;return begin(resumed);}return begin(fresh(SCENES[key].level,prefs.difficulty));}if(LEVELS[target])begin(fresh(target,prefs.difficulty));else if(SCENES[target])playScene(target);else if(target==='complete'){if(missionReplay)missionComplete();else complete();}}
function finishLevel(){if(!missionReplay){rememberOutcome(saved,model);persist();}if(model.inland)return playScene(LEVELS[model.level].after);if(model.south)return playScene(LEVELS[model.level].after);if(model.wider)return playScene(LEVELS[model.level].after);if(model.winter)return playScene(LEVELS[model.level].after);if(model.albany)return playScene(LEVELS[model.level].after);if(model.philadelphia)return playScene(LEVELS[model.level].after);if(model.crossing)return playScene(LEVELS[model.level].after);if(model.retreat)return playScene(LEVELS[model.level].after);if(model.paper)return playScene(LEVELS[model.level].after);if(model.lift)return playScene(LEVELS[model.level].after);if(model.promise)return playScene(LEVELS[model.level].after);if(missionReplay){if(model.level==='breeds')return playScene('hillEnding');if(model.level==='ticonderoga')return playScene('northEnding');return missionComplete();}resetInput();dialogue.stop();const scene={release:'gate',night:'lexington',lexington:'concordIntro',concord:'ending',ticonderoga:'northEnding',breeds:'hillEnding'}[model.level];playScene(scene);}
function complete(){saved.complete=true;saved.completedPart='inland';saved.scene=null;saved.checkpoint=null;persist();hide();setState('complete');music.select('home');music.resume();panel(`<p class="eyebrow">Country Against Itself · Complete</p><h1>Leave tomorrow open.</h1><p>The section came out of Camden’s defeat. An oath changed one family’s papers; Thomas’s property notice carried a separate loss. The household reached shelter, and the dated supply work continues under Greene.</p><p>Next: Make Them Chase, with Morgan’s separate force. Later Chapter 6 missions remain in development.</p><div class="row">${btn('Back to the road','home')}${btn('Remember these events','archive','secondary')}${btn('Replay scenes','scenes','quiet')}</div>`,true);}
function pause(){if(!['play','film'].includes(state))return;beforePause=state;dialogue.pause();music.pause();fxContext?.suspend();resetInput();setState('pause');pausePanel();}
function pausePanel(){setState('pause');panel(`<p class="eyebrow">Paused · ${beforePause==='film'?'Story scene':esc(LEVELS[model?.level]?.title||'The Powder Road')}</p><h1>Take a breath.</h1><div class="row">${btn('Resume','resume')}${btn('Settings','settings','secondary')}${btn('Controls','pause-controls','quiet')}</div><div class="row">${beforePause==='play'?btn('Restart checkpoint','retry','quiet'):btn('Restart scene','restart-scene','quiet')}${btn('Return to title','home','quiet')}</div><p class="save-warning">${missionReplay?'This replay leaves your story checkpoint intact.':storageOK?'Your last checkpoint is saved.':'Browser saving is unavailable in this session.'}</p>`,true);}
function resume(){ui.innerHTML='';setState(beforePause);dialogue.resume();if(beforePause!=='film'||SCENES[film?.key]?.music)music.resume();fxContext?.resume();last=performance.now();canvas.focus();}
function fail(){dialogue.stop();music.pause();resetInput();setState('failed');panel(`<p class="eyebrow">The road is still there</p><h1>Find cover. Try again.</h1><p>${model.level==='tidewater'?'Use C in the reeds to lose the lanterns. Dodge the marked shots; use Shift to pull away from the pursuing boat.':model.level==='camdenfall'?'Leave the exposed ditch once the section is rallied. Stay close to all four through the wooded turns, crouch while reloading and wait for the last man at each marker.':model.level==='breeds'?'Stay at the earthworks during the assaults. Direct volleys when they are close, crouch to reload, and use your reserve. During withdrawal, the rear earthworks give you shelter.':model.level==='night'?'Break the patrol’s line of sight. Crouch behind fences and take the orchard route.':'Use the stone wall while reloading. Crouch to stay below incoming fire.'}</p><div class="row">${btn('Restart checkpoint','retry')}${btn('Use Story difficulty','story-retry','secondary')}${btn('Return to title','home','quiet')}</div>`,true);}
