function action(name,el){document.body.dataset.lastAction=name;music.unlock();fxContext?.resume();if(name==='home')home();else if(name==='start')start();else if(name==='missions')missions();else if(name==='mission'){missionReplay=true;replayCheckpoint=null;if(LEVELS[el.dataset.mission].intro)playScene(LEVELS[el.dataset.mission].intro);else begin(fresh(el.dataset.mission,prefs.difficulty));}else if(name==='campaign'){missionReplay=false;start();}else if(name==='new-story')newStory();else if(name==='confirm-new'){saved.complete=false;saved.checkpoint=null;saved.scene='release';saved.completedPart=null;saved.seen=[];saved.skipped=[];saved.outcomes={};missionReplay=false;persist();start();}else if(name==='chapters')chapters();else if(name==='scenes')scenes();else if(name==='scene')playScene(el.dataset.scene,true);else if(name==='archive')archive();else if(name==='controls')controls();else if(name==='pause-controls')controls('pause-back');else if(name==='pause-back')pausePanel();else if(name==='settings')settings();else if(name==='settings-done'){persist();settingsBack==='pause'?pausePanel():home();}else if(name==='pause')pause();else if(name==='resume')resume();else if(name==='next')advance();else if(name==='skip')finishScene(true);else if(name==='restart-scene')playScene(film.key,replay);else if(name==='retry')retry();else if(name==='story-retry'){prefs.difficulty='story';persist();retry();}else if(name==='retry-render'){world=null;worldError=null;if(ensureWorld())home();else errorScreen();}}
