document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.key==='KeyC'){touchCrouch=!touchCrouch;return;}if(b.dataset.key==='KeyQ'){touchAim=!touchAim;return;}keys[b.dataset.key]=true;pressed[b.dataset.key]=(pressed[b.dataset.key]||0)+1;if(winterWashing(model)&&['KeyA','KeyD'].includes(b.dataset.key))washStrokes.push(b.dataset.key==='KeyA'?'a':'d');if(b.dataset.key==='KeyE')interacting=true;});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>keys[b.dataset.key]=false);});
window.addEventListener('blur',()=>{if(['play','film'].includes(state))pause();});document.addEventListener('visibilitychange',()=>{music.setHidden(document.hidden);if(document.hidden&&['play','film'].includes(state))pause();});window.addEventListener('resize',()=>world?.resize());
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();pause();worldError=new Error('Graphics context lost');});canvas.addEventListener('webglcontextrestored',()=>{world=null;ensureWorld();home();});
function frame(now){const frameStart=performance.now(),raw=(now-last)/1000,dt=Math.min(.05,Math.max(0,raw));last=now;time+=dt;
 try{
  if(state==='play'){
   if(keys.KeyW||keys.KeyA||keys.KeyS||keys.KeyD)interacting=false;
   const control=input(),events=tick(model,control,dt);pressed={};dialogue.update(dt);
   for(const e of events){if(e.type==='voice')say(e.id);else if(e.type==='checkpoint'){interacting=false;checkpoint();if(model.level==='tidewater')music.select(model.stage>=4?'battle':model.stage>=3?'tension':'tide');if(model.level==='breeds')music.select(hillDefending(model)?'ridge':'tension');if(model.level==='night'&&model.stage===2)say('ridge');if(model.level==='release'&&model.stage===1)say('releasewalk');}else if(e.type==='hillVolley'){fx('shot',.7);for(const x of [-17,-8,1,10]){world.smoke(x,1.6,1.2);world.trace(x,1.6,x,-25);}}else if(e.type==='volleyOrder'){interacting=false;say('hill.volley');}else if(e.type==='shell'){fx('shot',.9);world.smoke(e.x,e.z,3.5);}else if(e.type==='promiseScene'){playScene(e.key);break;}else if(e.type==='albanyScene'){playScene(e.key);break;}else if(e.type==='douse'){fx('foot',.25);world.smoke(e.x,e.z,.6);}else if(e.type==='navalShot'){fx('enemyShot',.25);world.smoke(e.x,e.z,.7);world.trace(e.x,e.z,model.player.x,model.player.z);}else if(e.type==='inlandVolley'){fx('shot',.4);world.smoke(model.player.x,model.player.z-2,.6);}else if(e.type==='southShellWarning'){fx('wood',.15);}else if(e.type==='southVolley'){fx('shot',.55);world.smoke(model.player.x,model.player.z-3,.65);}else if(e.type==='widerVolley'){fx('shot',.55);world.smoke(model.player.x,model.player.z-3,.65);}else if(e.type==='washStroke'){fx('foot',.2);}else if(e.type==='targetHit'){fx('wood',.5);world.smoke(e.x,e.z,.22);}else if(e.type==='axeStroke'){fx('wood',.65);}else if(e.type==='treeFall'){fx('wood',.8);world.smoke(-1,-24,.4);}else if(e.type==='albanyVolley'){fx('shot',.55);world.smoke(model.player.x,model.player.z,1);world.trace(model.player.x,model.player.z,0,-40);}else if(e.type==='philadelphiaVolley'){fx('shot',.55);world.smoke(-14,-8,1);world.trace(-14,-8,0,-40);}else if(e.type==='bridgeBreak'){fx('wood',.8);world.smoke(0,-52,1.6);}else if(e.type==='crossingVolley'){fx('shot',.55);world.smoke(model.player.x,model.player.z,1);world.trace(model.player.x,model.player.z,0,-40);}else if(e.type==='retreatVolley'){fx('shot',.5);world.smoke(-12,7,1);world.trace(-12,7,-8,-22);}else if(e.type==='orderUsed'){interacting=false;}else if(e.type==='oar'){fx('foot',.15);}else if(e.type==='paperAction'){interacting=false;fx('wood',.3);}else if(e.type==='pressStroke'){fx('wood',.6);}else if(e.type==='paperGust'){fx('foot',.25);}else if(e.type==='wood'){fx('wood',.3);}else if(e.type==='loadSlip'){fx('wood',.6);interacting=false;}else if(e.type==='waterShot'){fx('shot',.55);world.smoke(e.x,e.z,.55);}else if(e.type==='hillBreak'){playScene('hillBreak');break;}else if(e.type==='fortCapture'){playScene('fortCapture');break;}else if(e.type==='finish'){if(!dialogue.current&&!dialogue.queue.length)finishLevel();break;}else if(e.type==='fail'){fail();break;}else if(e.type==='shot'){fx('shot');world.smoke(e.x-Math.sin(model.player.yaw),e.z-Math.cos(model.player.yaw));}else if(e.type==='enemyShot'){fx('shot',Math.min(.5,10/Math.max(1,distance(model.player,e))));world.smoke(e.x,e.z,.75);world.trace(e.x,e.z,model.player.x,model.player.z);}else if(e.type==='volley'){fx('shot',.8);for(const x of [-7,-2,3,7]){world.smoke(x,-23,1.6);world.trace(x,-23,model.player.x+x*.2,model.player.z);}}else if(e.type==='resupply'){interacting=false;checkpoint();fx('wood',.4);}else if(e.type==='rescue')fx('wood',.25);else if(e.type==='hurt'){fx('hurt',.4);hurtUntil=time+.28;}else if(e.type==='bell'){fx('bell');world.bellUntil=model.time+2;}else if(e.type==='reload'||e.type==='loaded')fx('wood',.25);}
   if(state==='play'&&model.finished&&!dialogue.current&&!dialogue.queue.length)finishLevel();
   if(state==='play'){world.render(model,control,dt,{reduced:prefs.reduced,voice:captionSpeaker});updateHUD();if(model.level!=='tidewater'&&(control.forward||control.back||control.left||control.right)&&time-footTime>(control.sprint?.30:.46)){footTime=time;fx('foot');}}
  }else if(state==='film'&&film){const f=film,spec=SCENES[f.key],line=voices.get(spec.lines[f.beat]);f.time+=dt;f.elapsed+=dt;dialogue.update(dt);
   const lead=sceneLead(f.beat),hold=sceneHold(f.key,f.beat);if(!f.spoken&&f.time>lead){f.spoken=true;say(line.id);}
   if(f.key==='promiseContact'&&f.beat===8&&!f.shot){f.shot=true;fx('shot',.4);world.smoke(27,-80,.8);}
   if(f.key==='lexington'&&f.beat===2&&!f.shot){f.shot=true;fx('shot',.75);world.smoke(1,-20,3);if(!prefs.reduced)hurtUntil=time+.08;}
   world.film(f.key,f.beat,f.time,dt,{speaking:f.spoken&&!!dialogue.current,reduced:prefs.reduced,elapsed:f.elapsed});$('film-progress').style.width=((f.beat+Math.min(1,f.time/(line.duration+lead+hold)))/spec.lines.length*100)+'%';document.querySelector('.film-title').style.opacity=f.beat===0&&f.time<4.5?'1':'0';canvas.dataset.scene=f.key;canvas.dataset.beat=String(f.beat);
   if(f.spoken&&!dialogue.current&&f.time>lead+line.duration+hold)advance();
  }else if(['menu','chapters','scenes','archive','complete','missions','mission-complete','new-story'].includes(state)){if(ensureWorld())world.menu(time,dt);}
  $('impact').style.opacity=time<hurtUntil&&!prefs.reduced?'.6':'0';
 }catch(e){console.error('Chapter 6 frame:',e);setState('error');panel(`<h1>The scene stopped.</h1><p>Your last checkpoint is saved. Reload to try again.</p>${btn('Return to title','home')}`,true);}
 canvas.dataset.renderMs=(performance.now()-frameStart).toFixed(1);canvas.dataset.frameMs=(raw*1000).toFixed(0);requestAnimationFrame(frame);
}
configure();home();requestAnimationFrame(frame);document.body.dataset.version=VERSION;







